INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Vergleich in Python immer den Wert prüft?', 2, '[{"text": "Nein", "correct": true, "because": "`is` prüft Identität"}, {"text": "Ja", "correct": false, "because": "Nicht nur Wert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Schlüsselwort prüft in Python, ob zwei Objekte identisch sind?', 3, '[{"text": "is", "correct": true, "because": "Vergleicht Objektidentität"}, {"text": "==", "correct": false, "because": "Prüft Wertgleichheit"}, {"text": "!=", "correct": false, "because": "Ungleichheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften prüft ein Operator in Programmiersprachen?', 5, '[{"text": "Speicheradresse", "correct": true, "because": "Identität basiert darauf"}, {"text": "Objekttyp", "correct": true, "because": "Muss oft übereinstimmen"}, {"text": "Variable Länge", "correct": false, "because": "Nicht relevant"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) `is` prüft Identität in Python. b) `===` prüft nur Werte in JavaScript.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "`===` prüft Wert und Typ"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich zwei Objekte in Python vergleiche?', 4, '[{"text": "Speicherort", "correct": false, "because": "Entscheidend für Identität"}, {"text": "Objekt-ID", "correct": false, "because": "Basis der Prüfung"}, {"text": "Kommentarfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Vergleich in JavaScript immer Typen ignoriert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "`===` prüft Typen"}, {"text": "Ja", "correct": false, "because": "`==` konvertiert Typen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator prüft in JavaScript sowohl Wert als auch Typ?', 3, '[{"text": "===", "correct": true, "because": "Strenger Vergleich"}, {"text": "==", "correct": false, "because": "Nur Wert"}, {"text": "!=", "correct": false, "because": "Ungleichheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede gibt es zwischen Wert- und Identitätsprüfung?', 5, '[{"text": "Speicheradresse", "correct": true, "because": "Identität prüft diese"}, {"text": "Typprüfung", "correct": true, "because": "Bei Identität oft implizit"}, {"text": "Zeichenlänge", "correct": false, "because": "Nicht entscheidend"}, {"text": "Farbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) `is` in Python Typen prüft und b) `===` in JavaScript nur Werte vergleicht. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "`is` prüft Identität, `===` Typ und Wert"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Identität in Python zu prüfen?', 4, '[{"text": "Objekt-ID", "correct": false, "because": "Grundlage für `is`"}, {"text": "Speicheradresse", "correct": false, "because": "Implizit geprüft"}, {"text": "Variable Länge", "correct": true, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Prüft `===` in JavaScript die Speicheradresse?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Wert und Typ"}, {"text": "Ja", "correct": false, "because": "Keine Identitätsprüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein strenger Vergleich in JavaScript?', 4, '[{"text": "Typensicherheit", "correct": true, "because": "Vermeidet Konvertierung"}, {"text": "Genauigkeit", "correct": true, "because": "Präziser als `==`"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Identitätsprüfung immer Werte vergleicht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Speicherort"}, {"text": "Ja", "correct": false, "because": "Werte sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit `is` in Python?', 3, '[{"text": "Objektgleichheit", "correct": true, "because": "Prüft Identität"}, {"text": "Wertvergleich", "correct": false, "because": "Für `==`"}, {"text": "Typkonvertierung", "correct": false, "because": "Nicht Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) `is` ist für None geeignet. b) `===` prüft Speicher in JavaScript.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "`===` prüft Typ/Wert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich, um zwei Listen in Python auf Identität zu prüfen?', 4, '[{"text": "`is`", "correct": true, "because": "Vergleicht Objektidentität"}, {"text": "`==`", "correct": false, "because": "Vergleicht Inhalte"}, {"text": "`!=`", "correct": false, "because": "Ungleichheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob `is` in Python Typen ignoriert?', 2, '[{"text": "No", "correct": true, "because": "Typen müssen übereinstimmen"}, {"text": "Yes", "correct": false, "because": "Identität beachtet Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Identitätsprüfung nützlich?', 5, '[{"text": "Objektvergleich", "correct": true, "because": "Prüft exakte Instanz"}, {"text": "Effizienz", "correct": true, "because": "Schneller als Wertprüfung"}, {"text": "Wertänderung", "correct": false, "because": "Nicht Zweck"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist `===` in JavaScript dasselbe wie `is` in Python?', 3, '[{"text": "No", "correct": true, "because": "Unterschiedliche Prüfungen"}, {"text": "Yes", "correct": false, "because": "`is` prüft Identität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Identitätsvergleich?', 4, '[{"text": "Prüfen, ob zwei Variablen dasselbe Objekt sind", "correct": true, "because": "Typischer Einsatz"}, {"text": "Vergleich von Zahlenwerten", "correct": false, "because": "Wertprüfung"}, {"text": "Textlängen messen", "correct": false, "because": "Anderer Zweck"}]');
